    const root = this.containerEl.children[1];
    root.empty();
    root.addClass("gsd-status-root");
    // Render a top toolbar with refresh button (replaces the old sidebar)
    const toolbar = root.createDiv({ cls: "gsd-status-toolbar" });
    toolbar.createEl("h3", { text: "Projects Dashboard", cls: "gsd-status-toolbar-title" });
    const refreshBtn = toolbar.createEl("button", { cls: "gsd-status-btn", text: "\u21BB Refresh" });
    refreshBtn.addEventListener("click", () => this.doPoll());
    // Render all projects as a grid
