    const prefix = `gsd-term-${(projectPath || workspaceName).replace(/[^a-zA-Z0-9_.\/-]/g, "_")}`;
    const locationPrefix = (String(projectPath || workspaceName || "main").split("/").filter(Boolean).pop() || "main")
      .toLowerCase()
      .replace(/[^a-z0-9_.-]+/g, "-")
      .replace(/-+/g, "-")
