    const summary = container.createDiv({ cls: "gsd-session-count-summary" });
    const addMetric = (label, value) => {
      const metric = summary.createDiv({ cls: "gsd-session-count-metric" });
      metric.createSpan({ cls: "gsd-session-count-value", text: String(value) });
      metric.createSpan({ cls: "gsd-session-count-label", text: label });
    };
    addMetric("tmux sessions", counts.total);
    addMetric("open here", counts.openCount);
